package com.alsafa.native4;import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.widget.TextView;import com.alsafa.native4.core.*;import java.text.SimpleDateFormat;import java.util.*;
public final class AdvancedHomeActivity extends Activity{private CoreDb db;private Native4Services services;@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_advanced_home);db=new CoreDb(this);services=new Native4Services(db,"native4-android-alpha");findViewById(R.id.pageBack).setOnClickListener(v->finish());go(R.id.openSimple,SimpleHomeActivity.class);go(R.id.openSale,SaleActivity.class);go(R.id.openRepair,RepairActivity.class);go(R.id.openHandover,HandoverActivity.class);go(R.id.openSearch,SearchActivity.class);go(R.id.openProducts,ProductActivity.class);go(R.id.openPurchases,PurchaseActivity.class);go(R.id.openOnline,OnlineSaleActivity.class);go(R.id.openQuickRepair,DirectPartSaleActivity.class);go(R.id.openCash,CashActivity.class);go(R.id.openClosing,ClosingActivity.class);go(R.id.openReports,ReportsActivity.class);go(R.id.openSettings,SettingsActivity.class);Nav5.bind(this,R.id.navHome);refresh();}
@Override protected void onResume(){super.onResume();if(services!=null)refresh();}
private void go(int id,Class<?> c){findViewById(id).setOnClickListener(v->startActivity(new Intent(this,c)));}
private void refresh(){try{((TextView)findViewById(R.id.advancedSync)).setText("المزامنة: الحالة غير مؤكدة — تحقق من سجل العمليات");DeveloperTodaySummaryStore.Summary s=services.developerToday.read(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));((TextView)findViewById(R.id.advancedMoney)).setText("المدوّر من الإقفال السابق\n"+money(s.carry)+"\n\nمبيعات اليوم\n"+money(s.sales)+"\n\nصيانة اليوم\n"+money(s.repairs));InventorySummaryStore.Summary inv=new InventorySummaryStore(db).read();((TextView)findViewById(R.id.lowStock)).setText("المخزون — المنتجات: "+inv.products+"   |   الوحدات: "+inv.units+"\nتنبيه المخزون المنخفض (1 أو أقل): "+inv.lowStock);}catch(Exception e){((TextView)findViewById(R.id.advancedMoney)).setText("تعذر قراءة ملخص اليوم: "+msg(e));}}
private static String money(DeveloperTodaySummaryStore.Money m){return String.format(Locale.US,"USD %.2f   |   TRY %.2f   |   SYP %.2f",m.usd,m.tryAmount,m.syp);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}}
